const out = [];
for (const email of ['amy.lau@example.com', 'henry.ho@example.com', 'fiona.fung@example.com']) {
  await sleep(300);
  const rows = [...document.querySelectorAll('[data-account-row]')];
  const row = rows.find(r => r.textContent.includes(email));
  row.click();
  await sleep(30);
  const busyState = { busy: row.getAttribute('aria-busy'), spinner: !!row.querySelector('.animate-spin'), othersDisabled: rows.filter(r => r !== row).every(r => r.getAttribute('aria-disabled') === 'true') };
  await sleep(1500);
  const h1 = document.querySelector('h1')?.textContent.trim();
  const caps = [...document.querySelectorAll('li span:first-child')].map(s => s.textContent).slice(0,3);
  out.push({ email, path: location.pathname, h1, busyState, caps, cookie: document.cookie, ls: localStorage.length, ss: sessionStorage.length });
  [...document.querySelectorAll('button')].find(b => b.textContent.trim()==='Sign out').click();
  await sleep(1500);
}
out.push({ finalPath: location.pathname })
out

