window.__audit = () => {
  const parse = c => { const m = c.match(/[\d.]+/g).map(Number); return { r: m[0], g: m[1], b: m[2], a: m[3] ?? 1 } };
  const lum = ({r,g,b}) => { const f = v => { v/=255; return v <= .03928 ? v/12.92 : ((v+.055)/1.055)**2.4 }; return .2126*f(r)+.7152*f(g)+.0722*f(b) };
  const blend = (fg, bg, a) => ({ r: fg.r*a + bg.r*(1-a), g: fg.g*a + bg.g*(1-a), b: fg.b*a + bg.b*(1-a) });
  const bgOf = el => { let stack = []; for (let e = el; e; e = e.parentElement) { const c = parse(getComputedStyle(e).backgroundColor); if (c.a > 0) stack.push(c); if (c.a === 1) break; } let base = {r:255,g:255,b:255}; for (const c of stack.reverse()) base = blend(c, base, c.a); return base };
  const opacityOf = el => { let o = 1; for (let e = el; e; e = e.parentElement) o *= parseFloat(getComputedStyle(e).opacity); return o };
  const res = [];
  const walker = document.createTreeWalker(document.getElementById('one-tap-card'), NodeFilter.SHOW_TEXT);
  const seen = new Set();
  while (walker.nextNode()) { const n = walker.currentNode; if (!n.textContent.trim()) continue; const el = n.parentElement; if (seen.has(el)) continue; seen.add(el);
    const cs = getComputedStyle(el); const fg = parse(cs.color); const bg = bgOf(el); const eff = blend(fg, bg, fg.a * opacityOf(el));
    const l1 = lum(eff), l2 = lum(bg); const ratio = (Math.max(l1,l2)+.05)/(Math.min(l1,l2)+.05);
    res.push({ t: n.textContent.trim().slice(0,28), ratio: +ratio.toFixed(2) }); }
  return { min: Math.min(...res.map(r => r.ratio)), worst: res.sort((a,b) => a.ratio-b.ratio).slice(0,4), count: res.length };
};
({scheme: matchMedia('(prefers-color-scheme: dark)').matches ? 'dark' : 'light', ...window.__audit()})

